style.css:
@-moz-document domain("chatgpt.com") {
/* ============================================================
   1. WALLPAPER
   ============================================================ */
body {
  background:
    radial-gradient(ellipse 80% 65% at  8% 12%, #C8DEFF, transparent 58%),
    radial-gradient(ellipse 65% 75% at 88%  8%, #DEC8FF, transparent 54%),
    radial-gradient(ellipse 75% 55% at 52% 92%, #C8FFE0, transparent 58%),
    radial-gradient(ellipse 55% 65% at 92% 72%, #FFE0C8, transparent 52%),
    linear-gradient(145deg, #C8DEFF 0%, #DEC8FF 30%, #C8FFE0 60%, #FFE0C8 100%) !important;
  background-attachment: fixed !important;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", sans-serif !important;
}


/* ============================================================
   2. STRIP INTERMEDIATE CONTAINERS
   ============================================================ */

body > div,
body > div > div,
body > div > div > div,
body > div > div > div > div {
  background: transparent !important;
  background-color: transparent !important;
}

[data-scroll-root],
[data-voice-floating-orb-focus-background] {
  background: transparent !important;
  background-color: transparent !important;
}

main#main,
#thread,
#thread > div,
#thread > div > div,
#thread > div > div > div {
  background: transparent !important;
  background-color: transparent !important;
}

/* Composer wrappers — use data-type instead of escaped class name */
.composer-parent,
.composer-parent > div,
form[data-type="unified-composer"],
form[data-type="unified-composer"] > div {
  background: transparent !important;
  background-color: transparent !important;
}

#thread-bottom-container,
#thread-bottom,
#thread-bottom > div {
  background: transparent !important;
  background-color: transparent !important;
  border-top: none !important;
  box-shadow: none !important;
}

/* Kill the white-gradient fade ChatGPT overlays above the composer */
.content-fade::before,
.content-fade::after {
  content: none !important;
}

#stage-slideover-sidebar > div,
#stage-slideover-sidebar > div > div,
#stage-slideover-sidebar .overflow-y-auto {
  background: transparent !important;
  background-color: transparent !important;
}

/* Strip sidebar surface-primary token elements by attribute match */
#stage-slideover-sidebar [class*="bg-token-main-surface-primary"],
#stage-slideover-sidebar [class*="sidebar-surface-primary"],
#stage-slideover-sidebar [class*="bg-token-surface-primary"] {
  background: transparent !important;
  background-color: transparent !important;
}

nav[aria-label="Chat history"] .sticky,
nav[aria-label="Chat history"] > div.sticky {
  background: transparent !important;
  background-color: transparent !important;
}

#stage-slideover-sidebar > div > div:last-child {
  background: transparent !important;
  background-color: transparent !important;
}


/* ============================================================
   3. SIDEBAR — Level 1 Glass
   ============================================================ */
#stage-slideover-sidebar {
  background: rgba(255, 255, 255, 0.62) !important;
  backdrop-filter: blur(28px) saturate(2.0) !important;
  -webkit-backdrop-filter: blur(28px) saturate(2.0) !important;
  border-right: 0.5px solid rgba(255, 255, 255, 0.55) !important;
  box-shadow: 2px 0 20px rgba(0, 0, 0, 0.04),
              inset -1px 0 0 rgba(255, 255, 255, 0.35) !important;
}


/* ============================================================
   4. HEADER — Level 2 Glass
   ============================================================ */
header#page-header {
  background: rgba(255, 255, 255, 0.55) !important;
  backdrop-filter: blur(28px) saturate(1.9) !important;
  -webkit-backdrop-filter: blur(28px) saturate(1.9) !important;
  border-bottom: 0.5px solid rgba(255, 255, 255, 0.45) !important;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.70),
              0 4px 24px rgba(0, 0, 0, 0.04) !important;
}


/* ============================================================
   5. COMPOSER PILL — Level 3 Glass
   ============================================================ */
[data-composer-surface="true"] {
  background: rgba(255, 255, 255, 0.85) !important;
  backdrop-filter: blur(24px) saturate(1.8) !important;
  -webkit-backdrop-filter: blur(24px) saturate(1.8) !important;
  border: 0.5px solid rgba(255, 255, 255, 0.80) !important;
  box-shadow: 0 4px 32px rgba(0, 0, 0, 0.08),
              0 2px 8px rgba(0, 0, 0, 0.04),
              inset 0 1px 0 rgba(255, 255, 255, 0.95) !important;
}

.ProseMirror,
#prompt-textarea,
[class*="prosemirror"] {
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
}


/* ============================================================
   6. HOMEPAGE SUGGESTION CHIPS
   ============================================================ */
[data-testid="use-case-prompt-chips"] button {
  background: rgba(255, 255, 255, 0.52) !important;
  backdrop-filter: blur(12px) saturate(1.6) !important;
  -webkit-backdrop-filter: blur(12px) saturate(1.6) !important;
  border: 0.5px solid rgba(255, 255, 255, 0.65) !important;
  border-radius: 100px !important;
  box-shadow: 0 1px 6px rgba(0, 0, 0, 0.04) !important;
  transition: background 120ms ease, box-shadow 120ms ease !important;
}

[data-testid="use-case-prompt-chips"] button:hover {
  background: rgba(255, 255, 255, 0.80) !important;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.07) !important;
}


/* ============================================================
   7. DROPDOWN / POPOVER MENUS
   ============================================================ */
[role="menu"] {
  background: rgba(255, 255, 255, 0.85) !important;
  backdrop-filter: blur(20px) saturate(1.8) !important;
  -webkit-backdrop-filter: blur(20px) saturate(1.8) !important;
  border: 0.5px solid rgba(255, 255, 255, 0.65) !important;
  border-radius: 14px !important;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12),
              inset 0 1px 0 rgba(255, 255, 255, 0.90) !important;
}


/* ============================================================
   8. USER MESSAGE BUBBLES — iMessage blue
   .user-message-bubble-color is the actual ChatGPT class.
   Shape (squircle mask) is preserved; only fill is changed.
   ============================================================ */
.user-message-bubble-color {
  background: #007AFF !important;
  color: #ffffff !important;
  box-shadow: 0 4px 16px rgba(0, 122, 255, 0.30) !important;
}

.user-message-bubble-color * {
  color: #ffffff !important;
}


/* ============================================================
   9. CODE BLOCKS
   Fix: CSS L3 forbids complex selectors inside :not().
   Use cascade override instead of code:not(pre code).
   ============================================================ */
pre {
  background: rgba(0, 0, 0, 0.07) !important;
  border: 0.5px solid rgba(0, 0, 0, 0.08) !important;
  border-radius: 10px !important;
}

code {
  background: rgba(0, 0, 0, 0.06) !important;
  border-radius: 4px !important;
  padding: 1px 5px !important;
}

/* Override back for code inside pre — cascade wins over :not() */
pre code {
  background: transparent !important;
  border-radius: 0 !important;
  padding: 0 !important;
  border: none !important;
}


/* ============================================================
   10. DIALOG / MODAL
   ============================================================ */
dialog {
  background: rgba(0, 0, 0, 0.12) !important;
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
}

dialog > div,
[role="dialog"] {
  background: rgba(255, 255, 255, 0.78) !important;
  backdrop-filter: blur(40px) saturate(2.0) !important;
  -webkit-backdrop-filter: blur(40px) saturate(2.0) !important;
  border: 0.5px solid rgba(255, 255, 255, 0.70) !important;
  box-shadow: 0 40px 100px rgba(0, 0, 0, 0.14),
              inset 0 1px 0 rgba(255, 255, 255, 0.95) !important;
  border-radius: 20px !important;
}

[role="dialog"] nav,
[role="dialog"] aside {
  background: rgba(255, 255, 255, 0.45) !important;
  border-radius: 14px !important;
}


/* ============================================================
   11. FORM CONTROLS
   ============================================================ */
input:not([type="range"]):not([type="file"]):not([type="checkbox"]):not([type="radio"]):not(#prompt-textarea),
textarea:not(#prompt-textarea),
select {
  background: rgba(255, 255, 255, 0.65) !important;
  box-shadow: 0 0 0 0.5px rgba(0, 0, 0, 0.10) !important;
  border-radius: 8px !important;
}

input:not([type="range"]):not([type="file"]):not([type="checkbox"]):not([type="radio"]):not(#prompt-textarea):focus-visible,
textarea:not(#prompt-textarea):focus-visible {
  background: rgba(255, 255, 255, 0.92) !important;
  box-shadow: 0 0 0 3px rgba(0, 122, 255, 0.15),
              0 0 0 0.5px rgba(0, 0, 0, 0.10) !important;
  outline: none !important;
}

fieldset {
  background: transparent !important;
  border: none !important;
}


/* ============================================================
   12. POLISH
   ============================================================ */
* {
  scrollbar-width: thin !important;
  scrollbar-color: rgba(0, 0, 0, 0.14) transparent !important;
}

::selection {
  background: rgba(0, 122, 255, 0.18) !important;
}

button:focus-visible,
a:focus-visible {
  outline: 2px solid #007AFF !important;
  outline-offset: 2px !important;
}

input, textarea, [contenteditable] {
  caret-color: #007AFF !important;
}

nav a, button, input {
  transition: all 120ms cubic-bezier(0.4, 0, 0.2, 1) !important;
}
}
